def findRelativeRanks(score):
    # Step 1: Copy and sort the scores in descending order
    sorted_scores = score[:]
    for i in range(len(sorted_scores)):
        for j in range(i + 1, len(sorted_scores)):
            if sorted_scores[i] < sorted_scores[j]:
                # Swap elements
                sorted_scores[i], sorted_scores[j] = sorted_scores[j], sorted_scores[i]

    # Step 2: Create a rank mapping
    rank_mapping = {}
    for i in range(len(sorted_scores)):
        if i == 0:
            rank_mapping[sorted_scores[i]] = "Gold Medal"
        elif i == 1:
            rank_mapping[sorted_scores[i]] = "Silver Medal"
        elif i == 2:
            rank_mapping[sorted_scores[i]] = "Bronze Medal"
        else:
            rank_mapping[sorted_scores[i]] = str(i + 1)

    # Step 3: Assign ranks based on the original score array
    answer = []
    for s in score:
        answer.append(rank_mapping[s])

    return answer

# Example usage:
print(findRelativeRanks([5, 4, 3, 2, 1]))  # Output: ["Gold Medal", "Silver Medal", "Bronze Medal", "4", "5"]
print(findRelativeRanks([10, 3, 8, 9, 4]))  # Output: ["Gold Medal", "5", "Bronze Medal", "Silver Medal", "4"]

