def stringShift(s, shift):
    net_shift = 0
    for direction, amount in shift:
        if direction == 0:  
            net_shift -= amount
        else:  
            net_shift += amount
    n = len(s)
    net_shift %= n
    if net_shift < 0:
        net_shift += n
    if net_shift == 0:
        return s
    result = [''] * n
    for i in range(n):
        new_index = (i + net_shift) % n
        result[new_index] = s[i]
    return ''.join(result)
s1 = "abc"
shift1 = [[0, 1], [1, 2]]
print(stringShift(s1, shift1))  
s2 = "abcdefg"
shift2 = [[1, 1], [1, 1], [0, 2], [1, 3]]
print(stringShift(s2, shift2))

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right
def invertTree(root):
    if root is None:
        return None
    left_inverted = invertTree(root.left)
    right_inverted = invertTree(root.right)
    root.left = right_inverted
    root.right = left_inverted
    return root

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next
def deleteNodes(head, m, n):
    current = head
    previous = None
    while current:
        keep_count = 0
        while current and keep_count < m:
            previous = current
            current = current.next
            keep_count += 1
        remove_count = 0
        while current and remove_count < n:
            current = current.next
            remove_count += 1
        if previous:
            previous.next = current
    return head

