def longestCommonSubsequence(text1, text2):
    m = len(text1)
    n = len(text2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text1[i - 1] == text2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]
print(longestCommonSubsequence("abcde", "ace"))  
print(longestCommonSubsequence("abc", "abc"))    
print(longestCommonSubsequence("abc", "def"))

class Solution:
    def equationsPossible(self, equations):
        parent = list(range(26))  
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]
        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootY] = rootX
        for eq in equations:
            if eq[1] == '=':
                var1 = ord(eq[0]) - ord('a')
                var2 = ord(eq[3]) - ord('a')
                union(var1, var2)
        for eq in equations:
            if eq[1] == '!':
                var1 = ord(eq[0]) - ord('a')
                var2 = ord(eq[3]) - ord('a')
                if find(var1) == find(var2):
                    return False
        return True
sol = Solution()
print(sol.equationsPossible(["a==b", "b!=a"]))  
print(sol.equationsPossible(["b==a", "a==b"]))  
print(sol.equationsPossible(["a==b", "b==c", "a==c"]))  
print(sol.equationsPossible(["a==b", "b!=c", "c==a"]))  
print(sol.equationsPossible(["c==c", "b==d", "x!=z"]))

