        self.val = val
        self.left = left
        self.right = right

def findNearestRightNode(root, u):
    if not root:
        return None

    # Initialize the queue with the root node
    queue = [root]

    while queue:
        level_size = len(queue)

        for i in range(level_size):
            node = queue.pop(0)

            # Check if the current node is the target node 'u'
            if node == u:
                # If 'u' is not the last node in the current level, return the next node
                if i < level_size - 1:
                    return queue.pop(0)
                else:
                    # If 'u' is the last node, return None
                    return None

            # Add the children of the current node to the queue
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)

# Example usage:
# Construct the tree for example 1
root = TreeNode(1)
root.left = TreeNode(2)
root.right = TreeNode(3)
root.left.right = TreeNode(4)
root.right.left = TreeNode(5)
root.right.right = TreeNode(6)

u = root.left.right  # Node with value 4
print(findNearestRightNode(root, u).val)  # Output: 5

