def min_swaps(data):
    total_ones = 0
    for num in data:
        if num == 1:
            total_ones += 1
    if total_ones <= 1:
        return 0
    window_size = total_ones
    current_zeros = 0
    min_zeros = float('inf')
    for i in range(window_size):
        if data[i] == 0:
            current_zeros += 1
    min_zeros = min(min_zeros, current_zeros)
    for i in range(window_size, len(data)):
        if data[i - window_size] == 0:
            current_zeros -= 1
        if data[i] == 0:
            current_zeros += 1
        min_zeros = min(min_zeros, current_zeros)
    return min_zeros
