def minRemoveToMakeValid(s):
    # First pass: remove unmatched ')'
    result = []
    open_count = 0
    for char in s:
        if char == '(':
            open_count += 1
            result.append(char)
        elif char == ')':
            if open_count > 0:
                open_count -= 1
                result.append(char)
        else:
            result.append(char)

    # Second pass: remove unmatched '('
    close_count = 0
    final_result = []
    for char in reversed(result):
        if char == ')':
            close_count += 1
            final_result.append(char)
        elif char == '(':
            if close_count > 0:
                close_count -= 1
                final_result.append(char)
        else:
            final_result.append(char)

    # The final result is in reverse order, so reverse it again
    final_result.reverse()

    return ''.join(final_result)

# Example usage:
print(minRemoveToMakeValid("lee(t(c)o)de)"))  # Output: "lee(t(c)o)de"
print(minRemoveToMakeValid("a)b(c)d"))       # Output: "ab(c)d"
print(minRemoveToMakeValid("))(("))          # Output: ""
print(minRemoveToMakeValid("(a(b(c)d)"))      # Output: "a(b(c)d)"

