def maxSizeSlices(slices):
    def maxNonCircular(s):
        n = len(s)
        k = n // 3
        dp = [[0] * (k + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            for j in range(1, k + 1):
                if i > 1:
                    dp[i][j] = max(dp[i][j], dp[i-1][j])
                if i > 2:
                    dp[i][j] = max(dp[i][j], dp[i-2][j-1] + s[i-1])
        return dp[n][k]
    case1 = maxNonCircular(slices[1:])
    case2 = maxNonCircular(slices[:-1])
    return max(case1, case2)
print(maxSizeSlices([1,2,3,4,5,6]))  
print(maxSizeSlices([8,9,8,6,1,1]))  
print(maxSizeSlices([4,1,2,5,8,3,1,9,7]))  
print(maxSizeSlices([3,1,2]))

