class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.size = [1] * n

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        root_u = self.find(u)
        root_v = self.find(v)
        if root_u != root_v:
            if self.rank[root_u] > self.rank[root_v]:
                self.parent[root_v] = root_u
                self.size[root_u] += self.size[root_v]
            elif self.rank[root_u] < self.rank[root_v]:
                self.parent[root_u] = root_v
                self.size[root_v] += self.size[root_u]
            else:
                self.parent[root_v] = root_u
                self.size[root_u] += self.size[root_v]
                self.rank[root_u] += 1
            return True
        return False

def maxNumEdgesToRemove(n, edges):
    alice_uf = UnionFind(n)
    bob_uf = UnionFind(n)

    # Process type 3 edges first
    edges_used = 0
    for t, u, v in edges:
        if t == 3:
            if alice_uf.union(u - 1, v - 1):
                bob_uf.union(u - 1, v - 1)
                edges_used += 1

    # Process type 1 edges
    for t, u, v in edges:
        if t == 1:
            if alice_uf.union(u - 1, v - 1):
                edges_used += 1

    # Process type 2 edges
    for t, u, v in edges:
        if t == 2:
            if bob_uf.union(u - 1, v - 1):
                edges_used += 1

    # Check if both Alice and Bob can traverse the entire graph
    if alice_uf.size[alice_uf.find(0)] != n or bob_uf.size[bob_uf.find(0)] != n:
        return -1

    return len(edges) - edges_used

# Example usage:
print(maxNumEdgesToRemove(4, [[3,1,2],[3,2,3],[1,1,3],[1,2,4],[1,1,2],[2,3,4]]))  # Output: 2
print(maxNumEdgesToRemove(4, [[3,1,2],[3,2,3],[1,1,4],[2,1,4]]))  # Output: 0
print(maxNumEdgesToRemove(4, [[3,2,3],[1,1,2],[2,3,4]]))  # Output: -1

