def min_operations_to_subsequence(target, arr):
    # Step 1: Map elements of target to their indices
    target_map = {}
    for i, num in enumerate(target):
        target_map[num] = i

    # Step 2: Transform arr into a sequence of indices from target
    transformed_arr = []
    for num in arr:
        if num in target_map:
            transformed_arr.append(target_map[num])

    # Step 3: Find the length of the LIS in the transformed sequence
    def length_of_lis(sequence):
        if not sequence:
            return 0

        # This will store the smallest tail of all increasing subsequences
        # with different lengths
        lis = []

        for num in sequence:
            # Find the position where this number can replace or extend the LIS
            pos = 0
            while pos < len(lis) and lis[pos] < num:
                pos += 1

            # If pos is equal to the length of lis, it means we can extend the LIS
            if pos == len(lis):
                lis.append(num)
            else:
                # Otherwise, replace the element at pos
                lis[pos] = num

        return len(lis)

    lis_length = length_of_lis(transformed_arr)

    # Step 4: Calculate the minimum number of insertions
    return len(target) - lis_length

# Example usage:
target1 = [5, 1, 3]
arr1 = [9, 4, 2, 3, 4]
print(min_operations_to_subsequence(target1, arr1))  # Output: 2

target2 = [6, 4, 8, 1, 3, 2]
arr2 = [4, 7, 6, 2, 3, 8, 6, 1]
print(min_operations_to_subsequence(target2, arr2))  # Output: 3

