def minDistance(word1, word2):
    m, n = len(word1), len(word2)

    # Create a 2D array to store the minimum operations
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize the base cases
    for i in range(1, m + 1):
        dp[i][0] = i  # Deleting all characters from word1
    for j in range(1, n + 1):
        dp[0][j] = j  # Inserting all characters into word1

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j - 1],  # Replace
                               dp[i - 1][j],      # Delete
                               dp[i][j - 1]) + 1   # Insert

    # The answer is in the bottom-right corner of the table
    return dp[m][n]

# Example usage:
print(minDistance("horse", "ros"))  # Output: 3
print(minDistance("intention", "execution"))  # Output: 5

